styleSheets.cssText:
:root { --navy: #102b43; --navy-deep: #0c2236; --orange: #ff8a3d; --orange-button: #fc8637; --paper: #f5f7f8; --ink: #112b42; --muted: #65737e; --line: #dce3e7; --white: #fff; --font: Arial,Helvetica,sans-serif; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 108px; }
body { margin: 0px; font-family: var(--font); color: var(--ink); background: rgb(255, 255, 255); font-size: 16px; line-height: 1.55; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }
button { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible { outline: rgb(189, 87, 17) solid 3px; outline-offset: 5px; }
img { display: block; max-width: 100%; }
svg.icon { width: 24px; height: 24px; flex: 0 0 auto; fill: none; stroke: currentcolor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.icon-definitions { position: absolute; width: 0px; height: 0px; overflow: hidden; }
.container { width: min(1280px, 100% - 96px); margin: auto; }
.skip-link { position: fixed; top: 12px; left: 12px; padding: 12px 20px; background: white; z-index: 1000; transform: translateY(-150%); }
.skip-link:focus { transform: translateY(0px); }
.header { height: 104px; background: white; position: sticky; top: 0px; z-index: 30; border-bottom: 1px solid rgb(230, 235, 239); }
.header-inner { height: 100%; display: flex; align-items: center; justify-content: space-between; gap: 25px; }
.brand { display: inline-flex; align-items: center; gap: 11px; flex-shrink: 0; }
.brand-mark { width: 58px; height: 58px; object-fit: contain; }
.brand-type { display: flex; flex-direction: column; }
.brand-type strong { font-weight: 600; font-size: 28px; letter-spacing: 1.05px; line-height: 1.3; }
.brand-dot { color: rgb(217, 95, 17); }
.brand-type > span { font-size: 8.5px; letter-spacing: 1.05px; font-weight: 600; line-height: 1.5; }
.desktop-nav { display: flex; gap: 28px; align-items: center; font-size: 14px; font-weight: 600; }
.desktop-nav a { position: relative; padding: 15px 0px; }
.desktop-nav a::after { content: ""; height: 2px; background: rgb(232, 108, 26); width: 0px; position: absolute; bottom: 4px; left: 0px; transition: width 0.2s; }
.desktop-nav a:hover::after, .desktop-nav a.active::after { width: 100%; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 18px; padding: 18px 24px; background: var(--orange-button); color: rgb(18, 40, 58); border: 1px solid transparent; border-radius: 3px; font-size: 15px; font-weight: 700; line-height: 1.3; transition: background 0.18s, transform 0.18s; min-height: 56px; }
.button:hover { background: rgb(255, 155, 87); transform: translateY(-2px); }
.button-small { font-size: 14px; padding: 14px 19px; min-height: 48px; gap: 13px; }
.button-small .icon { width: 19px; height: 19px; }
.menu-toggle { display: none; }
.mobile-nav[hidden] { display: none; }
.hero { background: var(--navy); color: white; position: relative; overflow: hidden; }
.hero-grid { display: grid; grid-template-columns: 1fr 1.08fr; gap: 45px; padding-top: 55px; padding-bottom: 50px; align-items: center; }
.eyebrow { display: flex; align-items: center; gap: 12px; font-size: 12px; letter-spacing: 1.55px; font-weight: 600; color: rgb(213, 224, 232); margin: 0px 0px 26px; line-height: 1.5; }
.eyebrow > span { display: block; width: 28px; height: 2px; background: var(--orange); flex-shrink: 0; }
.hero h1 { font-size: clamp(48px, 4.45vw, 68px); font-weight: 600; letter-spacing: -2.8px; line-height: 1.055; margin: 0px 0px 26px; }
em { font-style: normal; color: var(--orange); }
.hero-description { font-size: 17px; line-height: 1.8; color: rgb(198, 211, 221); max-width: 440px; margin: 0px 0px 31px; }
.hero-actions { display: flex; align-items: center; gap: 23px; flex-wrap: wrap; }
.text-link { font-size: 14px; font-weight: 600; display: inline-flex; align-items: center; gap: 12px; padding: 12px 0px; }
.text-link .icon { width: 20px; height: 20px; transition: transform 0.2s; }
.text-link:hover .icon { transform: translateX(4px); }
.hero-note { display: flex; align-items: center; gap: 9px; color: rgb(202, 215, 224); font-size: 13px; margin-top: 22px; }
.hero-note .icon { width: 17px; height: 17px; color: var(--orange); }
.hero-visual { margin: 0px; position: relative; align-self: stretch; min-height: 490px; border-radius: 4px; isolation: isolate; }
.hero-visual > img { width: 100%; height: 100%; position: absolute; inset: 0px; object-fit: cover; object-position: 61% center; border-radius: 4px; }
.visual-label { position: absolute; left: -22px; bottom: 33px; padding: 19px 21px; background: white; color: var(--navy); display: flex; align-items: center; gap: 40px; box-shadow: rgba(0, 0, 0, 0.133) 0px 10px 30px; border-left: 3px solid var(--orange); }
.visual-label span { font-size: 12px; letter-spacing: 1.2px; font-weight: 700; }
.visual-label .icon { width: 23px; height: 23px; color: rgb(201, 90, 19); }
.hero-visual figcaption { position: absolute; right: 13px; bottom: 9px; font-size: 12px; line-height: 1.5; color: white; background: rgba(16, 43, 67, 0.808); padding: 2px 7px; border-radius: 2px; }
.image-corner { position: absolute; right: -9px; top: -9px; width: 90px; height: 90px; border-right: 2px solid var(--orange); border-top: 2px solid var(--orange); z-index: -1; }
.reassurance { border-top: 1px solid rgba(255, 255, 255, 0.145); display: flex; align-items: center; justify-content: space-between; padding-top: 24px; padding-bottom: 25px; gap: 18px; color: rgb(220, 229, 236); font-size: 14px; }
.reassurance > span, .reassurance > a { display: flex; align-items: center; gap: 10px; }
.reassurance .icon { color: var(--orange); width: 20px; height: 20px; }
.reassurance > a { font-size: 13px; color: rgb(192, 208, 220); }
.reassurance > a .icon { margin-left: 5px; }
.section { padding: 82px 0px; }
.services { background: var(--paper); }
.section-heading { display: flex; justify-content: space-between; gap: 40px; align-items: flex-end; margin-bottom: 39px; }
.eyebrow.dark { color: rgb(101, 117, 130); font-size: 12px; margin-bottom: 20px; }
.eyebrow.dark > span { background: rgb(220, 105, 29); }
h2 { font-size: 40px; font-weight: 600; line-height: 1.16; letter-spacing: -1.4px; margin: 0px; }
.section-heading > p { max-width: 330px; color: var(--muted); font-size: 16px; line-height: 1.75; margin: 0px 0px 3px; }
.service-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
.service-card { background: white; border: 1px solid rgb(225, 231, 235); border-radius: 4px; padding: 24px 23px 53px; position: relative; min-height: 245px; transition: box-shadow 0.2s, border-color 0.2s, transform 0.2s; }
.service-card:hover, .service-card:focus-within { border-color: rgb(244, 173, 127); box-shadow: rgba(16, 43, 67, 0.04) 0px 8px 22px; transform: translateY(-3px); }
.service-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 22px; }
.service-top > .icon { color: rgb(182, 81, 18); width: 30px; height: 30px; stroke-width: 1.4; }
.service-top > span { font-size: 12px; color: rgb(138, 150, 158); font-variant-numeric: tabular-nums; }
.service-card h3 { font-size: 17px; line-height: 1.35; letter-spacing: -0.25px; margin: 0px 0px 12px; font-weight: 700; min-height: 46px; }
.service-card p { font-size: 14px; line-height: 1.6; color: var(--muted); margin: 0px; max-width: 230px; }
.service-link { position: absolute; bottom: 12px; right: 13px; width: 38px; height: 38px; display: flex; align-items: center; justify-content: center; border-radius: 50%; transition: background 0.2s; }
.service-link:hover, .service-link:focus-visible { background: rgb(255, 240, 228); }
.service-link .icon { width: 19px; height: 19px; }
.services-bottom { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-top: 25px; }
.services-bottom > p { font-size: 14px; color: rgb(96, 113, 128); margin: 0px; }
.dark-link { color: rgb(156, 68, 13); }
.about { background: white; padding: 74px 0px; }
.about-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 90px; }
.about-copy > p { color: rgb(101, 117, 129); line-height: 1.9; font-size: 17px; margin: 0px 0px 28px; }
.director { display: flex; align-items: center; gap: 14px; }
.director-initials { width: 48px; height: 48px; background: rgb(241, 244, 246); border: 1px solid rgb(225, 230, 234); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 600; }
.director > span:nth-child(2) { display: flex; flex-direction: column; gap: 2px; font-size: 15px; }
.director > span:nth-child(2) > span { color: rgb(109, 125, 136); font-size: 13px; }
.director-rule { height: 1px; background: var(--line); flex: 1 1 0%; margin-left: 16px; }
.contact { padding: 8px 0px 66px; }
.contact-panel { background: var(--navy); border-radius: 5px; display: grid; grid-template-columns: 1.25fr 1fr; gap: 80px; padding: 58px 65px; color: white; position: relative; overflow: hidden; }
.contact-copy .eyebrow { margin-bottom: 20px; }
.contact h2 { font-size: 50px; line-height: 1.1; letter-spacing: -1.8px; }
.contact-copy > p:not(.eyebrow) { font-size: 16px; color: rgb(195, 210, 221); line-height: 1.85; margin: 23px 0px 28px; }
.contact-copy > .button { font-size: 14px; gap: 15px; }
.contact-copy > .button > .icon { width: 20px; height: 20px; }
.contact-details { align-self: center; border-left: 1px solid rgba(255, 255, 255, 0.145); padding-left: 48px; }
.contact-person { font-size: 12px; font-weight: 600; letter-spacing: 1.6px; color: rgb(173, 192, 206); margin: 0px 0px 13px; }
.contact-details h3 { font-size: 26px; letter-spacing: -0.4px; font-weight: 500; margin: 0px 0px 2px; }
.contact-details > p:not(.contact-person) { font-size: 14px; color: rgb(185, 202, 215); margin: 0px; }
.contact-links { margin-top: 20px; }
.contact-links > a { display: flex; align-items: center; gap: 14px; padding: 17px 0px; border-bottom: 1px solid rgba(255, 255, 255, 0.145); }
.contact-links > a > .icon:first-child { color: var(--orange); width: 20px; height: 20px; }
.contact-links > a > span { font-size: 18px; line-height: 1.45; flex: 1 1 0%; }
.contact-links small { display: block; font-size: 12px; color: rgb(182, 200, 212); margin-top: 2px; }
.contact-links > a > .icon:last-child { width: 19px; height: 19px; color: rgb(182, 200, 212); transition: transform 0.2s; }
.contact-links > a:hover > .icon:last-child { transform: translate(2px, -2px); color: white; }
.contact-area { display: flex; gap: 12px; align-items: center; margin-top: 23px; color: rgb(195, 209, 219); font-size: 14px; }
.contact-area > .icon { width: 20px; height: 20px; color: var(--orange); }
footer { border-top: 1px solid rgb(224, 230, 233); padding-top: 30px; background: rgb(255, 255, 255); }
.footer-top { display: flex; justify-content: space-between; align-items: center; gap: 25px; padding-bottom: 30px; }
.footer-top .brand-mark { width: 45px; height: 45px; }
.footer-top .brand-type strong { font-size: 22px; }
.footer-top .brand-type > span { font-size: 7px; letter-spacing: 0.7px; }
.footer-top > span { font-size: 14px; color: rgb(111, 126, 136); }
.back-top { font-size: 13px; display: flex; gap: 13px; align-items: center; }
.back-top > .icon { width: 18px; height: 18px; }
.footer-bottom { border-top: 1px solid rgb(227, 232, 235); display: flex; justify-content: space-between; gap: 25px; padding-top: 20px; padding-bottom: 24px; font-size: 12px; color: rgb(107, 123, 135); }
@media (min-width: 1550px) {
  .container { width: min(1400px, 100% - 128px); }
  .hero h1 { font-size: 76px; }
  .hero-visual { min-height: 525px; }
  .hero-grid { gap: 65px; }
}
@media (max-width: 1200px) {
  .container { width: calc(100% - 64px); }
  .desktop-nav { gap: 19px; }
  .brand-type strong { font-size: 24px; }
  .brand-mark { width: 48px; height: 48px; }
  .brand-type > span { font-size: 7px; }
  .header-inner { gap: 18px; }
  .hero-grid { gap: 30px; }
  .hero h1 { font-size: 55px; }
  .hero-description { font-size: 16px; }
  .hero-actions { gap: 10px; }
  .hero-actions .button { padding: 17px 19px; font-size: 14px; }
  .hero-actions .text-link { font-size: 13px; }
  .hero-visual { min-height: 470px; }
  .service-card { padding: 20px 18px 49px; }
  .service-card h3 { font-size: 16px; }
  .service-card p { font-size: 14px; }
  .contact-panel { padding: 50px; gap: 45px; }
  .contact-details { padding-left: 35px; }
  .reassurance > a { display: none; }
}
@media (max-width: 980px) {
  .desktop-nav { display: none; }
  .header-inner > .header-cta { margin-left: auto; }
  .menu-toggle { display: flex; width: 44px; height: 44px; flex-direction: column; justify-content: center; align-items: center; gap: 7px; border: 1px solid var(--line); background: white; border-radius: 3px; cursor: pointer; }
  .menu-toggle > span { display: block; width: 19px; height: 1.5px; background: var(--navy); transition: transform 0.2s; }
  .menu-toggle[aria-expanded="true"] > span:first-child { transform: translateY(4.25px) rotate(45deg); }
  .menu-toggle[aria-expanded="true"] > span:last-child { transform: translateY(-4.25px) rotate(-45deg); }
  .mobile-nav { display: flex; flex-direction: column; padding: 12px 32px 20px; background: white; border-top: 1px solid var(--line); box-shadow: rgba(16, 43, 67, 0.063) 0px 12px 14px; }
  .mobile-nav > a { padding: 12px 0px; font-size: 16px; }
  .header { height: 88px; }
  .hero-grid { grid-template-columns: 1fr 1fr; gap: 30px; padding-top: 44px; padding-bottom: 40px; }
  .hero h1 { font-size: 45px; letter-spacing: -1.7px; }
  .hero .eyebrow { font-size: 12px; letter-spacing: 1px; }
  .hero-description { font-size: 15px; }
  .hero-visual { min-height: 450px; }
  .visual-label { left: -12px; bottom: 38px; gap: 20px; padding: 15px; }
  .visual-label span { font-size: 12px; }
  .service-grid { grid-template-columns: repeat(3, 1fr); }
  .service-card { min-height: 240px; }
  .service-card:last-child { grid-column: span 3; display: grid; grid-template-columns: 0.4fr 1fr 1.3fr; gap: 20px; align-items: center; min-height: auto; padding: 23px 65px 23px 23px; }
  .service-card:last-child .service-top, .service-card:last-child h3 { margin: 0px; min-height: 0px; }
  .service-card:last-child .service-top > span { display: none; }
  .service-card:last-child br { display: none; }
  .service-card:last-child .service-link { bottom: calc(50% - 19px); }
  .about-grid { gap: 45px; }
  .about h2 { font-size: 34px; }
  .contact-panel { gap: 30px; padding: 40px 35px; }
  .contact-details { padding-left: 28px; }
  .contact h2 { font-size: 45px; }
  .contact-copy > .button { font-size: 13px; padding: 16px 18px; gap: 11px; }
  .contact-copy > .button > .icon:first-child { display: none; }
  .contact-links > a > span { font-size: 16px; }
  .footer-top > span { display: none; }
}
@media (max-width: 700px) {
  html { scroll-padding-top: 88px; }
  .container { width: calc(100% - 40px); }
  .header { height: 78px; }
  .header-inner { gap: 10px; }
  .brand { gap: 8px; }
  .brand-mark { width: 44px; height: 44px; }
  .brand-type strong { font-size: 22px; letter-spacing: 0.65px; }
  .brand-type > span { font-size: 6px; letter-spacing: 0.7px; }
  .header-inner > .header-cta { display: none; }
  .menu-toggle { margin-left: auto; }
  .hero-grid { grid-template-columns: 1fr; padding-top: 38px; padding-bottom: 29px; gap: 28px; }
  .hero .eyebrow { font-size: 12px; letter-spacing: 1.2px; margin-bottom: 20px; }
  .hero h1 { font-size: clamp(43px, 10.6vw, 62px); line-height: 1.07; letter-spacing: -1.8px; margin-bottom: 20px; }
  .hero h1 br:nth-of-type(1) { display: block; }
  .hero h1 br:nth-of-type(2) { display: block; }
  .hero-description { max-width: 480px; font-size: 16px; line-height: 1.7; margin-bottom: 24px; }
  .desktop-break { display: none; }
  .hero-actions { gap: 17px; }
  .hero-actions .button { font-size: 14px; padding: 17px 18px; min-height: 54px; }
  .hero-actions .text-link { font-size: 13px; gap: 8px; }
  .hero-actions .text-link > .icon { width: 17px; height: 17px; }
  .hero-note { margin-top: 16px; font-size: 12px; }
  .hero-visual { min-height: 0px; aspect-ratio: 1.35 / 1; max-height: 440px; margin: 8px 5px 0px; }
  .hero-visual > img { object-position: 55% center; }
  .visual-label { left: -5px; bottom: 29px; padding: 15px 16px; gap: 22px; }
  .visual-label span { font-size: 12px; letter-spacing: 1px; }
  .hero-visual figcaption { font-size: 12px; right: 7px; bottom: 5px; }
  .reassurance { padding-top: 21px; padding-bottom: 22px; display: grid; grid-template-columns: 1fr 1fr; gap: 16px 10px; font-size: 12px; }
  .reassurance > span { gap: 8px; }
  .reassurance > span:last-of-type { grid-column: span 2; }
  .reassurance .icon { width: 17px; height: 17px; }
  .section { padding: 52px 0px; }
  .section-heading { display: block; margin-bottom: 26px; }
  .eyebrow.dark { font-size: 12px; letter-spacing: 1.25px; margin-bottom: 17px; }
  h2 { font-size: 33px; letter-spacing: -1px; }
  .section-heading > p { font-size: 15px; max-width: 400px; margin: 20px 0px 0px; line-height: 1.7; }
  .service-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 10px; }
  .service-card { min-height: 241px; padding: 19px 16px 42px; }
  .service-top { margin-bottom: 19px; }
  .service-top > .icon { width: 27px; height: 27px; }
  .service-card h3 { font-size: 16px; line-height: 1.35; margin-bottom: 10px; min-height: 43px; }
  .service-card p { font-size: 14px; line-height: 1.55; }
  .service-card:last-child { grid-column: auto; display: block; min-height: 241px; padding: 19px 16px 42px; }
  .service-card:last-child .service-top { margin-bottom: 19px; }
  .service-card:last-child h3 { margin-bottom: 10px; min-height: 43px; }
  .service-card:last-child .service-top > span { display: block; }
  .service-card:last-child br { display: block; }
  .service-card:last-child .service-link { bottom: 12px; }
  .services-bottom { align-items: flex-start; gap: 10px; margin-top: 22px; }
  .services-bottom > p { font-size: 13px; max-width: 220px; }
  .services-bottom > a { padding: 0px; font-size: 13px; white-space: nowrap; gap: 7px; }
  .about-grid { grid-template-columns: 1fr; gap: 25px; }
  .about-copy > p { font-size: 16px; line-height: 1.8; margin-bottom: 24px; }
  .about h2 { font-size: 33px; }
  .contact { padding-top: 0px; padding-bottom: 40px; }
  .contact-panel { grid-template-columns: 1fr; gap: 38px; padding: 35px 25px; border-radius: 4px; }
  .contact-copy .eyebrow { font-size: 12px; letter-spacing: 1.05px; margin-bottom: 18px; }
  .contact h2 { font-size: 43px; letter-spacing: -1.6px; }
  .contact-copy > p:not(.eyebrow) { font-size: 15px; line-height: 1.75; margin: 20px 0px 25px; }
  .contact-copy > .button { font-size: 14px; padding: 17px 18px; gap: 14px; }
  .contact-copy > .button > .icon:first-child { display: block; }
  .contact-details { border-left: 0px; border-top: 1px solid rgba(255, 255, 255, 0.145); padding: 30px 0px 0px; }
  .contact-details h3 { font-size: 25px; }
  .contact-links { margin-top: 14px; }
  .contact-links > a > span { font-size: 18px; }
  .contact-person { font-size: 12px; }
  .contact-area { font-size: 14px; }
  .footer-top { gap: 20px; flex-wrap: wrap; padding-bottom: 22px; }
  .footer-top .brand-mark { width: 38px; height: 38px; }
  .footer-top .brand-type strong { font-size: 19px; }
  .footer-top .brand-type > span { font-size: 6px; }
  .back-top { font-size: 12px; gap: 6px; }
  .footer-bottom { flex-direction: column; gap: 7px; font-size: 12px; padding-top: 17px; padding-bottom: 23px; }
}
@media (max-width: 380px) {
  .container { width: calc(100% - 32px); }
  .brand-type strong { font-size: 20px; }
  .brand-mark { width: 39px; height: 39px; }
  .hero-actions { gap: 8px; }
  .hero-actions .button { padding: 16px 14px; font-size: 13px; gap: 10px; }
  .hero-actions .text-link { font-size: 12px; }
  .service-card, .service-card:last-child { padding-left: 13px; padding-right: 13px; min-height: 262px; }
  .contact-panel { padding: 32px 21px; }
  .contact-copy > .button { font-size: 13px; padding: 16px 13px; }
  .contact-copy > .button > .icon:first-child { display: none; }
  .back-top { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, ::before, ::after { transition: none !important; animation: auto ease 0s 1 normal none running none !important; }
}
